"""Run profiling/profile.sql block by block and write profiling/profile_results.md."""
import sys
import time
from pathlib import Path

sys.path.insert(0, str(Path(__file__).resolve().parents[1]))
from steamdb.db import connect, load_blocks, md_table, query  # noqa: E402

HERE = Path(__file__).resolve().parent


def main():
    conn = connect()
    conn.autocommit = True
    with conn.cursor() as cur:
        cur.execute("SET work_mem = '128MB'")
    out = ["# Data profile (raw files)\n",
           "Generated by `profiling/run_profile.py` from `profiling/profile.sql`.\n"]
    for name, sql in load_blocks(HERE / "profile.sql").items():
        if len(sys.argv) > 1 and name.split(".")[0] not in sys.argv[1:]:
            continue
        t = time.time()
        cols, rows = query(conn, sql)
        print(f"{name}  ({time.time() - t:.1f}s)", flush=True)
        out += [f"## {name}\n", md_table(cols, rows), ""]
    if len(sys.argv) == 1:
        (HERE / "profile_results.md").write_text("\n".join(out), encoding="utf-8")
    else:
        print("\n".join(out))
    conn.close()


if __name__ == "__main__":
    main()
